<?php
/**
 * Shared challenge validation for contact and registration forms.
 * The image itself is generated by modules/captcha.php; a code is only ever
 * accepted once, including after a failed attempt.
 */
if (!function_exists('kandagaCaptchaVerify')) {
    function kandagaCaptchaVerify($input): bool
    {
        $expected = (string)($_SESSION['captcha_code'] ?? '');
        $answer = is_string($input) ? strtoupper(trim($input)) : '';
        unset($_SESSION['captcha_code'], $_SESSION['captcha_generated_at']);
        if ($expected === '' || $answer === '') return false;
        return hash_equals($expected, $answer);
    }
}
